This Python function should remove duplicates while keeping order, but some inputs come back wrong. Find every bug and explain why:

def dedupe(items, seen=set()):
    out = []
    for i in range(len(items)):
        if items[i] in seen:
            items.pop(i)
        else:
            seen.add(items[i])
            out.append(items[i])
    return out
